#include <iostream>
#include <algorithm>
using namespace std;

int A[7], s;
bool ok;

void bkt(int poz, int sum) {
    if (ok) return;
    if (poz == 7) {
        if (2 * sum == s) ok = true;
        return;
    }

    bkt(poz + 1, sum + A[poz]);
    bkt(poz + 1, sum);
}

int main() {
    for (int i = 1; i <= 6; i++)
        cin >> A[i];

    sort(A + 1, A + 7);

    for (int i = 1; i <= 6; i++)
        s += A[i];

    bkt(1, 0);
    cout << (ok ? "YES" : "NO");

    return 0;
}

#include <iostream>
#include <algorithm>
using namespace std;

int A[7], s, ok, F[7];

void bkt(int poz)
{
    if (ok) return;

    if (poz == 7)
    {
        int sum = 0;
        for (int i = 1; i <= 6; i++)
            if (F[i] == 1)
                sum += A[i];

        if (2 * sum == s)
            ok = 1;
        return;
    }

    F[poz] = 1;
    bkt(poz + 1);

    F[poz] = 0;
    bkt(poz + 1);
}

int main()
{
    for (int i = 1; i <= 6; i++)
        cin >> A[i];

    sort(A + 1, A + 7);

    for (int i = 1; i <= 6; i++)
        s += A[i];

    bkt(1);

    cout << (ok ? "YES" : "NO");
    return 0;
}

