using namespace std;

int main() {
    long long A[6], total = 0;

    for (long long &x : A) {
        cin >> x;
        total += x;
    }

    for (int mask = 0; mask < (1 << 6); ++mask) {
        long long sum = 0;
        for (int i = 0; i < 6; ++i)
            if (mask & (1 << i))
                sum += A[i];

        if (2 * sum == total) {
            cout << "YES";
            return 0;
        }
    }

    cout << "NO";
    return 0;
}

